#include <vector>
#include <queue>
#include <utility>

class Solution {
public:
    double maxProbability(int n, std::vector<std::vector<int>>& edges, std::vector<double>& succProb, int start_node, int end_node) {
        std::vector<std::vector<std::pair<int, double>>> graph(n);
        for (size_t i = 0; i < edges.size(); ++i) {
            int u = edges[i][0], v = edges[i][1];
            double p = succProb[i];
            graph[u].push_back({v, p});
            graph[v].push_back({u, p});
        }
        std::vector<double> prob(n, 0.0);
        prob[start_node] = 1.0;
        std::priority_queue<std::pair<double, int>> pq;
        pq.push({1.0, start_node});
        while (!pq.empty()) {
            auto [curP, u] = pq.top();
            pq.pop();
            if (u == end_node) return curP;
            if (curP < prob[u]) continue;
            for (auto& [v, weight] : graph[u]) {
                if (curP * weight > prob[v]) {
                    prob[v] = curP * weight;
                    pq.push({prob[v], v});
                }
            }
        }
        return 0.0;
    }
};

import java.util.*;

class Solution {
    static class Node {
        int to;
        double p;
        Node(int to, double p) { this.to = to; this.p = p; }
    }
    public double maxProbability(int n, int[][] edges, double[] succProb, int start_node, int end_node) {
        List<Node>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0], v = edges[i][1];
            double p = succProb[i];
            graph[u].add(new Node(v, p));
            graph[v].add(new Node(u, p));
        }
        double[] prob = new double[n];
        prob[start_node] = 1.0;
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> Double.compare(b.p, a.p));
        pq.add(new Node(start_node, 1.0));
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.to == end_node) return cur.p;
            if (cur.p < prob[cur.to]) continue;
            for (Node nxt : graph[cur.to]) {
                if (cur.p * nxt.p > prob[nxt.to]) {
                    prob[nxt.to] = cur.p * nxt.p;
                    pq.add(new Node(nxt.to, prob[nxt.to]));
                }
            }
        }
        return 0.0;
    }
}

var maxProbability = function(n, edges, succProb, start_node, end_node) {
    const graph = Array.from({ length: n }, () => []);
    for (let i = 0; i < edges.length; i++) {
        const [u, v] = edges[i];
        const p = succProb[i];
        graph[u].push([v, p]);
        graph[v].push([u, p]);
    }
    const prob = new Array(n).fill(0.0);
    prob[start_node] = 1.0;
    const queue = [[1.0, start_node]];
    while (queue.length > 0) {
        queue.sort((a, b) => b[0] - a[0]);
        const [curP, u] = queue.shift();
        if (u === end_node) return curP;
        if (curP < prob[u]) continue;
        for (const [v, weight] of graph[u]) {
            if (curP * weight > prob[v]) {
                prob[v] = curP * weight;
                queue.push([prob[v], v]);
            }
        }
    }
    return 0.0;
};
